import React, { useState } from 'react';
import api from '../api';

function AddTrip({ setTrip }) {
    const [tripName, setTripName] = useState('');
    const [numMembers, setNumMembers] = useState(0);
    const [familyMembers, setFamilyMembers] = useState([]);
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    const handleAddTrip = async (e) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        try {
            if (!tripName || familyMembers.some(member => !member)) {
                setError('Please fill in all fields');
                return;
            }

            const tripData = {
                name: tripName,
                families: familyMembers.map(member => ({
                    head: member,
                    members: []
                }))
            };

            console.log('Sending trip data:', tripData);

            const response = await api.post('/trips', tripData);

            if (response?.data) {
                console.log('Trip created:', response.data);
                setTrip(response.data);
            } else {
                throw new Error('No response data received');
            }
        } catch (error) {
            console.error('Error creating trip:', error);
            setError(error.response?.data?.message || 'Failed to create trip. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleNumMembersChange = (e) => {
        const count = parseInt(e.target.value) || 0;
        setNumMembers(count);
        setFamilyMembers(Array(count).fill(''));
    };

    const handleMemberNameChange = (index, value) => {
        const updated = [...familyMembers];
        updated[index] = value;
        setFamilyMembers(updated);
    };

    return (
        <div style={{ maxWidth: '500px', margin: '0 auto', padding: '20px' }}>
            <form onSubmit={handleAddTrip}>
                <h2>Add New Trip</h2>

                {error && <div style={{ color: 'red', marginBottom: '10px' }}>{error}</div>}

                <div style={{ marginBottom: '15px' }}>
                    <label>Trip Name:</label>
                    <input
                        type="text"
                        value={tripName}
                        onChange={(e) => setTripName(e.target.value)}
                        style={{ width: '100%', padding: '8px', marginTop: '5px' }}
                        required
                    />
                </div>

                <div style={{ marginBottom: '15px' }}>
                    <label>Number of Families:</label>
                    <input
                        type="number"
                        value={numMembers}
                        onChange={handleNumMembersChange}
                        min="1"
                        style={{ width: '100%', padding: '8px', marginTop: '5px' }}
                        required
                    />
                </div>

                {familyMembers.map((name, index) => (
                    <div key={index} style={{ marginBottom: '15px' }}>
                        <label>Family Head {index + 1}:</label>
                        <input
                            type="text"
                            value={name}
                            onChange={(e) => handleMemberNameChange(index, e.target.value)}
                            style={{ width: '100%', padding: '8px', marginTop: '5px' }}
                            required
                        />
                    </div>
                ))}

                <button
                    type="submit"
                    style={{
                        width: '100%',
                        padding: '10px',
                        backgroundColor: '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                    }}
                >
                    {isLoading ? 'Creating Trip...' : 'Create Trip'}
                </button>
            </form>
        </div>
    );
}

export default AddTrip;
